import reactor.netty.resources.ConnectionProvider;

class NettyCP {
    public ConnectionProvider connectionProviderBad1() {
        return ConnectionProvider.builder("gupProvider")
                //.maxConnections(props.getMaxConnections()) // bad <-- this line was missing
                .pendingAcquireTimeout(Duration.ofMillis(props.getPendingAcquireTimeoutMs()))
                .pendingAcquireMaxCount(props.getPendingAcquireMaxCount())
                .maxIdleTime(props.getIdleTimeSeconds())
                .build();
    }
    public ConnectionProvider connectionProviderBad2() {
        return ConnectionProvider.builder("gupProvider")
                .maxConnections(props.getMaxConnections())
                //.pendingAcquireTimeout(Duration.ofMillis(props.getPendingAcquireTimeoutMs())) //bad
                .build();
    }
    public ConnectionProvider connectionProviderBad3() {
        return ConnectionProvider.builder("gupProvider")
                //.maxConnections(props.getMaxConnections()) //bad
                //.pendingAcquireTimeout(Duration.ofMillis(props.getPendingAcquireTimeoutMs()))
